from builtins import object
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
logger = BackgroundLogger.Instance()


try:
    from taf.gnb.oam.coam.vdu import vdu
except ImportError:
    logger.warn('TAF libraries unavailable for CBTS OAM operations. Ignore if the keywords are not used')


class Factory(object):

    INSTANCE = None

    def __init__(self):
        self.vdu_oam = vdu()

    @classmethod
    def get_instance(cls):
        if not cls.INSTANCE:
            cls.INSTANCE = Factory()
        return cls.INSTANCE
